/**
 * The score behind this repo's ranking — the whole of it, in one file.
 *
 * It ranks free chat models on what can be MEASURED, in three layers:
 *   1. Benchmarks  — Artificial Analysis indices (intelligence, coding,
 *                    agentic), which OpenRouter publishes in /api/v1/models.
 *   2. Preference  — LM Arena ratings (human votes): overall, coding,
 *                    instruction following.
 *   3. Prior       — for models nobody has measured yet: the measured quality
 *                    of a sibling in the same family, or real parameter count
 *                    and downloads from the Hugging Face model card. Capped, so
 *                    nothing unmeasured can outrank a well-measured model.
 * Then a "fitness" factor for things that matter when you build on a model:
 * context, output ceiling, tool calling, structured outputs, a published
 * shutdown date.
 *
 * This file is PURE: no network, no clock except the `today` argument. Data is
 * gathered by sources.js and passed in, so anyone can re-run it on the inputs
 * saved in data/models.json and get the same numbers.
 *
 * It is the same function ZeroLimitAI's router (zerolimitai.com) ranks with.
 * The router feeds it two extra inputs from its own production traffic —
 * `availabilityPenalty` and `latencyPenalty` — which nobody outside can
 * reproduce. Here they are left at 0, so this score is quality and fitness
 * only; the site's leaderboard can differ by those few points.
 *
 * @typedef {{ intelligence?: number|null, coding?: number|null, agentic?: number|null }} Benchmarks
 * @typedef {{ overall?: number|null, coding?: number|null, instruction_following?: number|null, spanish?: number|null, votes?: number|null }} Arena
 * @typedef {{ paramsB?: number|null, downloads?: number|null, pipelineTag?: string|null }} HfInfo
 * @typedef {object} ModelInput
 * @property {string} id                       OpenRouter id, e.g. "google/gemma-4-31b-it:free"
 * @property {number} contextLength
 * @property {number|null} [maxCompletionTokens]
 * @property {string[]} [outputModalities]
 * @property {boolean} [supportsTools]
 * @property {boolean} [supportsStructuredOutputs]
 * @property {boolean} [reasoningMandatory]
 * @property {string|null} [expirationDate]     ISO date
 * @property {Benchmarks|null} [benchmarks]
 * @property {Arena|null} [arena]
 * @property {HfInfo|null} [hf]
 * @property {number} [availabilityPenalty]     ≤ 0, production failures (not used here)
 * @property {number} [latencyPenalty]          ≤ 0, production latency (not used here)
 * @typedef {{ intelligence: number, coding: number, agentic: number }} Maxima
 * @typedef {object} Result
 * @property {string} id
 * @property {string|null} excluded             why it is not ranked as a chat model, or null
 * @property {number} quality                   0–100, before fitness
 * @property {number} score                     0–100-ish, the ordering key
 * @property {"benchmarks+arena"|"benchmarks"|"arena"|"family"|"prior"} basis
 * @property {string[]} notes
 */

// ── Tunables (one place, named) ──────────────────────────────────────────────

/** Audience: developers running coding assistants, bots and pipelines. */
export const BENCH_WEIGHTS = { intelligence: 0.45, coding: 0.35, agentic: 0.2 };
export const ARENA_WEIGHTS = { overall: 0.5, coding: 0.35, instruction_following: 0.15 };

/** Arena rating → 0–100. 1200 is a weak 2024 model, 1500 the 2026 frontier. */
export const ARENA_FLOOR = 1200;
export const ARENA_CEIL = 1500;

/** When both layers exist. Benchmarks measure what a model solves, the Arena
 *  what people prefer; they disagree often enough that neither decides alone. */
export const BLEND_BENCH = 0.55;
export const BLEND_ARENA = 0.45;
export const SINGLE_SOURCE_DISCOUNT = 0.92;

/**
 * A missing index is filled from the ones present, discounted — NOT dropped
 * with the weights renormalised, which rewards a model for reporting less
 * (a model with only a coding index would outrank its bigger sibling that also
 * reports a poor agentic score).
 * Ratios: median of (normalised index / normalised coding index) over the free
 * models that reported all three on 2026-09-21 — intelligence ≈ 0.70 of coding,
 * agentic ≈ 0.40 (agentic scores are low across the board).
 */
export const IMPUTE_FROM_CODING = { intelligence: 0.7, agentic: 0.4 };
export const IMPUTE_DISCOUNT = 0.9;

/** Production inputs, when a caller has them: failures are a tie-breaker (they
 *  mostly measure popularity), latency is a property of the model. */
const OPS_SCALE = 0.1;
const OPS_CAP = 8;
const LATENCY_SCALE = 0.2;
const LATENCY_CAP = 20;

/** Nothing unmeasured may outrank a well-measured model. */
export const PRIOR_CAP = 45;
export const FAMILY_INHERITANCE = 0.8;

const NOT_CHAT_ID = /safety|guard|moderation|embed|reward|rerank|\bocr\b/i;
const CHAT_PIPELINES = new Set(["text-generation", "image-text-to-text", "any-to-any", "conversational"]);

// ── Helpers ──────────────────────────────────────────────────────────────────

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
const isNum = (v) => typeof v === "number" && Number.isFinite(v);

/** "inclusionai/ling-3.0-flash-vl:free" → "inclusionai/ling-3.0-flash" */
export function familyKey(id) {
  const [org, rest = ""] = id.toLowerCase().replace(/:free$/, "").split("/");
  const tokens = rest.split("-");
  return `${org}/${tokens.slice(0, Math.max(1, Math.min(3, tokens.length - 1))).join("-")}`;
}

/** @param {Benchmarks|null|undefined} b @param {Maxima} max @param {string[]} notes */
function benchmarkQuality(b, max, notes) {
  if (!b) return null;
  const raw = {
    intelligence: isNum(b.intelligence) ? (b.intelligence / max.intelligence) * 100 : null,
    coding: isNum(b.coding) ? (b.coding / max.coding) * 100 : null,
    agentic: isNum(b.agentic) ? (b.agentic / max.agentic) * 100 : null,
  };
  const present = Object.values(raw).filter((v) => v !== null);
  if (present.length === 0) return null;

  // Anchor for imputation: coding if present (the most widely reported), else
  // the mean of what is present.
  const anchor = raw.coding ?? present.reduce((a, c) => a + c, 0) / present.length;
  const fromCoding = raw.coding !== null;
  const filled = {
    intelligence: raw.intelligence ?? anchor * (fromCoding ? IMPUTE_FROM_CODING.intelligence : 1) * IMPUTE_DISCOUNT,
    coding: raw.coding ?? anchor * IMPUTE_DISCOUNT,
    agentic: raw.agentic ?? anchor * (fromCoding ? IMPUTE_FROM_CODING.agentic : 1) * IMPUTE_DISCOUNT,
  };
  if (present.length < 3) notes.push(`benchmarks ${present.length}/3 (rest imputed)`);
  return clamp(
    filled.intelligence * BENCH_WEIGHTS.intelligence +
      filled.coding * BENCH_WEIGHTS.coding +
      filled.agentic * BENCH_WEIGHTS.agentic,
    0,
    100,
  );
}

/** @param {Arena|null|undefined} a */
function arenaQuality(a) {
  if (!a || !isNum(a.overall)) return null;
  const norm = (r) => clamp(((r - ARENA_FLOOR) / (ARENA_CEIL - ARENA_FLOOR)) * 100, 0, 100);
  const overall = norm(a.overall);
  // A category the arena has not rated yet falls back to the overall rating.
  const coding = isNum(a.coding) ? norm(a.coding) : overall;
  const instr = isNum(a.instruction_following) ? norm(a.instruction_following) : overall;
  return overall * ARENA_WEIGHTS.overall + coding * ARENA_WEIGHTS.coding + instr * ARENA_WEIGHTS.instruction_following;
}

/** @param {HfInfo|null|undefined} hf @param {string} id */
function priorQuality(hf, id) {
  // Parameter count: Hugging Face's real total if known, else a "27b" token in the id.
  let p = isNum(hf?.paramsB) ? hf.paramsB : null;
  if (p === null) {
    const m = id.toLowerCase().match(/(?<![a-z\d.])(\d+(?:\.\d+)?)b(?![a-z])/);
    p = m ? parseFloat(m[1]) : null;
  }
  let prior = p !== null ? 4.2 * Math.log2(1 + p) : 12;
  // Adoption: 1k downloads → 0, 10M → +5
  if (isNum(hf?.downloads) && hf.downloads > 0) {
    prior += clamp((Math.log10(hf.downloads) - 3) * 1.25, 0, 5);
  }
  return clamp(prior, 0, PRIOR_CAP);
}

// ── Scoring ──────────────────────────────────────────────────────────────────

/** @param {ModelInput} m @param {string} today */
function exclusionReason(m, today) {
  const outs = m.outputModalities ?? ["text"];
  if (!outs.every((o) => o === "text")) return "does not answer in text only";
  if (NOT_CHAT_ID.test(m.id)) return "not a chat model (classifier/embedding)";
  const tag = m.hf?.pipelineTag;
  if (m.hf && tag !== undefined && (tag === null || !CHAT_PIPELINES.has(tag))) {
    return `not a chat model (pipeline: ${tag ?? "none"})`;
  }
  if (m.expirationDate && m.expirationDate.slice(0, 10) <= today) return "expired";
  return null;
}

/** @param {ModelInput} m @param {string} today @param {string[]} notes */
function fitness(m, today, notes) {
  let f = 1;
  if (m.contextLength > 0 && m.contextLength < 32_000) {
    f *= 0.85;
    notes.push("context < 32k");
  }
  if (isNum(m.maxCompletionTokens) && m.maxCompletionTokens > 0 && m.maxCompletionTokens < 4096) {
    f *= 0.8;
    notes.push("max output < 4k");
  }
  if (m.reasoningMandatory) {
    f *= 0.85;
    notes.push("always reasons (slow first token)");
  }
  // People building agents and pipelines need both.
  if (m.supportsTools) f *= 1.05;
  else notes.push("no tool calling");
  if (m.supportsStructuredOutputs) f *= 1.03;
  if (m.expirationDate) {
    const days = Math.round((Date.parse(m.expirationDate.slice(0, 10)) - Date.parse(today)) / 86_400_000);
    notes.push(`expires in ${days}d`);
    if (days <= 7) f *= 0.7;
  }
  return f;
}

/**
 * Rank a pool. Two passes, because an unmeasured model may inherit from a
 * measured sibling in its family.
 *
 * @param {ModelInput[]} pool
 * @param {Maxima} maxima  the largest value of each benchmark index across the
 *                         WHOLE catalogue (paid models included), so 100 means
 *                         "as good as the best model anyone sells".
 * @param {string} today   YYYY-MM-DD
 * @returns {Result[]}     ranked models first (best first), excluded ones last
 */
export function rank(pool, maxima, today) {
  const measured = new Map(); // family → qualities
  const partial = pool.map((m) => {
    const notes = [];
    const excluded = exclusionReason(m, today);
    const bq = benchmarkQuality(m.benchmarks, maxima, notes);
    const aq = arenaQuality(m.arena);
    let quality = null;
    let basis = "prior";
    if (bq !== null && aq !== null) {
      quality = bq * BLEND_BENCH + aq * BLEND_ARENA;
      basis = "benchmarks+arena";
    } else if (bq !== null) {
      quality = bq * SINGLE_SOURCE_DISCOUNT;
      basis = "benchmarks";
    } else if (aq !== null) {
      quality = aq * SINGLE_SOURCE_DISCOUNT;
      basis = "arena";
    }
    if (quality !== null && !excluded) {
      const k = familyKey(m.id);
      measured.set(k, [...(measured.get(k) ?? []), quality]);
    }
    return { m, notes, excluded, quality, basis };
  });

  const results = partial.map(({ m, notes, excluded, quality, basis }) => {
    let q = quality;
    let b = basis;
    if (q === null) {
      const prior = priorQuality(m.hf, m.id);
      const sib = measured.get(familyKey(m.id));
      if (sib && sib.length > 0) {
        const sorted = [...sib].sort((x, y) => x - y);
        const median = sorted[Math.floor(sorted.length / 2)];
        q = Math.max(prior, clamp(median * FAMILY_INHERITANCE, 0, PRIOR_CAP + 10));
        b = "family";
        notes.push("unmeasured: inherits from a measured sibling");
      } else {
        q = prior;
        notes.push("unmeasured: prior from size and adoption");
      }
    }
    const f = fitness(m, today, notes);
    // Health is deliberately NOT part of the score: a model that is rate-limited
    // this hour is still the better model, and a ranking is read for longer than
    // an outage lasts. "Is it answering right now?" is a separate column.
    const failures = Math.max(-OPS_CAP, (m.availabilityPenalty ?? 0) * OPS_SCALE);
    const latency = Math.max(-LATENCY_CAP, (m.latencyPenalty ?? 0) * LATENCY_SCALE);
    if (failures < 0) notes.push(`failures ${Math.round(failures)}`);
    if (latency < 0) notes.push(`slow ${Math.round(latency)}`);
    return {
      id: m.id,
      excluded,
      quality: Math.round(q * 10) / 10,
      score: Math.round((q * f + failures + latency) * 10) / 10,
      basis: b,
      notes,
    };
  });

  return results.sort((a, b) => {
    if (!!a.excluded !== !!b.excluded) return a.excluded ? 1 : -1;
    return b.score - a.score;
  });
}

/**
 * Where the scoring inputs come from. Every source is public and needs no key:
 *
 *   OpenRouter  /api/v1/models                — catalogue, prices, capabilities
 *                                               and Artificial Analysis indices
 *   OpenRouter  /api/v1/models/{id}/endpoints — which provider actually serves
 *                                               the free endpoint
 *   LM Arena    lmarena-ai/leaderboard-dataset — human-preference ratings
 *   Hugging Face /api/models/{id}             — real parameter count, downloads
 *
 * Network failures never throw: a source that is down means that layer is
 * missing for today, and the score says so in its `basis`.
 */
import { parquetReadObjects } from "hyparquet";

const UA = { "User-Agent": "free-ai-models-tracker/2.0 (github.com/ClawLabsAI/free-ai-models)" };
const TIMEOUT_MS = 20_000;

async function getJson(url, timeout = TIMEOUT_MS) {
  try {
    const res = await fetch(url, { headers: { ...UA, Accept: "application/json" }, signal: AbortSignal.timeout(timeout) });
    return res.ok ? await res.json() : null;
  } catch {
    return null;
  }
}

/** Run `fn` over `items`, at most `n` at a time. */
async function pool(items, n, fn) {
  const out = new Array(items.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(n, items.length) }, async () => {
      while (next < items.length) {
        const i = next++;
        out[i] = await fn(items[i], i);
      }
    }),
  );
  return out;
}

// ── OpenRouter ───────────────────────────────────────────────────────────────

/** The whole OpenRouter catalogue. Throws: without it there is no list. */
export async function fetchOpenRouterModels() {
  const res = await fetch("https://openrouter.ai/api/v1/models", { headers: UA });
  if (!res.ok) throw new Error(`OpenRouter API ${res.status}: ${res.statusText}`);
  return (await res.json()).data;
}

export const isFree = (m) =>
  !!m.pricing && parseFloat(m.pricing.prompt) === 0 && parseFloat(m.pricing.completion) === 0;

/** Largest value of each Artificial Analysis index across the whole catalogue. */
export function benchmarkMaxima(allModels) {
  const max = (k) => Math.max(1, ...allModels.map((m) => m.benchmarks?.artificial_analysis?.[k] ?? 0));
  return {
    intelligence: max("intelligence_index"),
    coding: max("coding_index"),
    agentic: max("agentic_index"),
  };
}

// ── Data use: does the provider behind the free endpoint train on prompts? ───

/**
 * What OpenRouter's provider table says about the providers that serve free
 * models: https://openrouter.ai/docs/guides/privacy/provider-logging
 *
 * That table is rendered in the browser from data that has no public API, so
 * this is a copy, read by hand on POLICIES_CHECKED. Only the providers seen
 * behind a free endpoint are listed; anything else is reported as unknown
 * (null), never guessed. On that date the table had 93 providers and four
 * marked "May train": DeepSeek, Liquid, NVIDIA and Thinking Machines.
 * OpenRouter calls the table its best knowledge of each provider's own
 * policy, not a definitive source — and so is this.
 *
 * `retention` is how long the provider keeps prompts: "zero", a number of
 * days, or "unknown" when the table says "retained for unknown period".
 */
export const POLICIES_CHECKED = "2026-10-10";
export const PROVIDER_POLICIES = {
  "deepseek":          { trains: true,  retention: "unknown" },
  "liquid":            { trains: true,  retention: "unknown" },
  "nvidia":            { trains: true,  retention: "unknown" },
  "thinking machines": { trains: true,  retention: "unknown" },
  "atlascloud":        { trains: false, retention: "unknown" },
  "cerebras":          { trains: false, retention: "zero" },
  "chutes":            { trains: false, retention: "unknown" },
  "cohere":            { trains: false, retention: 30 },
  "google ai studio":  { trains: false, retention: 55 },
  "google vertex":     { trains: false, retention: "zero" },
  "groq":              { trains: false, retention: "zero" },
  "meta":              { trains: false, retention: 30 },
  "mistral":           { trains: false, retention: 30 },
  "modelrun":          { trains: false, retention: "zero" },
  "nex agi":           { trains: false, retention: 30 },
  "novitaai":          { trains: false, retention: "zero" },
  "poolside":          { trains: false, retention: "unknown" },
  "z.ai":              { trains: false, retention: "zero" },
};
// The endpoints API and the policy table do not always spell a name the same way.
const POLICY_ALIASES = { novita: "novitaai", "modelrun [by modular]": "modelrun", "nvidia nim": "nvidia" };

/** The policy row for a provider name as the endpoints API spells it, or null. */
export function providerPolicy(name) {
  const key = String(name ?? "").trim().toLowerCase();
  return PROVIDER_POLICIES[POLICY_ALIASES[key] ?? key] ?? null;
}

/**
 * Provider names behind a model's free endpoints, or null if unknown.
 * The author is not the provider: a lab's open model is often served for free
 * by a host with a different policy from the lab's own API.
 */
export async function fetchServingProviders(modelId) {
  const body = await getJson(`https://openrouter.ai/api/v1/models/${modelId}/endpoints`, 10_000);
  if (!body) return null;
  const endpoints = body.data?.endpoints ?? body.endpoints ?? [];
  const free = endpoints.filter((e) => Number(e.pricing?.prompt ?? "1") === 0);
  const names = (free.length ? free : endpoints).map((e) => e.provider_name).filter(Boolean);
  return names.length ? [...new Set(names)] : null;
}

/**
 * "no-training" — none of the providers serving it for free trains on prompts
 * "mixed"       — some do; OpenRouter can be told to use only the others with
 *                 `provider: { data_collection: "deny" }`
 * "may-train"   — every provider serving it for free may train on prompts
 * null          — unknown: the endpoints call failed, or a provider is not in
 *                 PROVIDER_POLICIES yet
 */
export function dataUse(providers) {
  if (!providers || providers.length === 0) return null;
  const rows = providers.map(providerPolicy);
  if (rows.some((r) => r === null)) return null;
  const training = rows.filter((r) => r.trains).length;
  if (training === 0) return "no-training";
  return training === providers.length ? "may-train" : "mixed";
}

/**
 * How long prompts are kept, when every provider serving the model agrees:
 * "zero", a number of days, "unknown", or null when they differ or are unlisted.
 */
export function retention(providers) {
  if (!providers || providers.length === 0) return null;
  const rows = providers.map(providerPolicy);
  if (rows.some((r) => r === null)) return null;
  const all = [...new Set(rows.map((r) => r.retention))];
  return all.length === 1 ? all[0] : null;
}

export async function fetchDataUse(modelIds) {
  const lists = await pool(modelIds, 5, fetchServingProviders);
  return new Map(modelIds.map((id, i) => [id, lists[i]]));
}

// ── LM Arena ─────────────────────────────────────────────────────────────────

const ARENA_PARQUET_URL =
  "https://huggingface.co/api/datasets/lmarena-ai/leaderboard-dataset/parquet/text/latest/0.parquet";
const ARENA_CATEGORIES = new Set(["overall", "coding", "instruction_following", "spanish"]);

/**
 * One canonical spelling for a model across OpenRouter ids and Arena names.
 *   "google/gemma-4-31b-it:free" / "gemma-4-31b-it" → "gemma-4-31b"
 *   "nvidia-nemotron-3-ultra-550b-a55b-nvfp4"       → "nemotron-3-ultra-550b-a55b"
 * Matching is EXACT on this form. Matching by substring is how an old "qwen3"
 * lends its rating to "qwen3.8-27b".
 */
export function normaliseName(name) {
  return name
    .toLowerCase()
    .replace(/:free$/, "")
    .replace(/^[^/]+\//, "") // org prefix
    .replace(/\s+/g, "-")
    .replace(/^nvidia-/, "")
    .replace(/-(bf16|fp8|fp4|nvfp4|int8|int4|awq|gptq)$/, "")
    .replace(/-(it|instruct|chat)$/, "");
}

/**
 * Same model, spelled with its size or quantisation appended?
 *   want "nemotron-3.5-lightning" vs arena "nemotron-3.5-lightning-30b-a3b" → yes
 *   want "glm-5.2"                vs arena "glm-5.2-max"                    → NO
 * Only size/precision/version tokens may follow; any other word is a different
 * product.
 */
const SIZE_TOKEN = /^(\d+(\.\d+)?b|a\d+(\.\d+)?b|bf16|fp8|fp4|nvfp4|int8|int4|v\d+(\.\d+)?)$/;
export function sameArenaModel(want, arenaName) {
  const n = normaliseName(arenaName);
  if (n === want) return true;
  if (!n.startsWith(want + "-")) return false;
  return n.slice(want.length + 1).split("-").every((t) => SIZE_TOKEN.test(t));
}

/** The text leaderboard (one ~600 KB file), or null if unavailable. */
export async function fetchArenaTable() {
  try {
    const res = await fetch(ARENA_PARQUET_URL, { headers: UA, signal: AbortSignal.timeout(TIMEOUT_MS) });
    if (!res.ok) return null;
    const rows = await parquetReadObjects({
      file: await res.arrayBuffer(),
      columns: ["model_name", "category", "rating", "vote_count"],
    });
    const out = [];
    for (const r of rows) {
      const category = String(r.category ?? "");
      if (!ARENA_CATEGORIES.has(category) || typeof r.rating !== "number") continue;
      out.push({
        model_name: String(r.model_name ?? ""),
        category,
        rating: r.rating,
        vote_count: typeof r.vote_count === "number" ? r.vote_count : null,
      });
    }
    // An empty table is a broken download, not "nobody is rated".
    return out.some((r) => r.category === "overall") ? out : null;
  } catch {
    return null;
  }
}

/**
 * One model's ratings out of the leaderboard (pure). When several spellings
 * match a category, the exact name wins, then the one with more votes.
 */
export function arenaFromRows(orId, rows) {
  const want = normaliseName(orId);
  const best = new Map();
  for (const r of rows) {
    if (!sameArenaModel(want, r.model_name)) continue;
    const exact = normaliseName(r.model_name) === want;
    const votes = r.vote_count ?? 0;
    const prev = best.get(r.category);
    if (!prev || (exact && !prev.exact) || (exact === prev.exact && votes > prev.votes)) {
      best.set(r.category, { rating: r.rating, votes, exact });
    }
  }
  const overall = best.get("overall");
  if (!overall) return null;
  const out = {};
  for (const [cat, v] of best) out[cat] = Math.round(v.rating);
  if (overall.votes > 0) out.votes = Math.round(overall.votes);
  return out;
}

// ── Hugging Face model card ──────────────────────────────────────────────────

export async function fetchHf(hfId) {
  const json = await getJson(`https://huggingface.co/api/models/${hfId}`);
  if (!json || typeof json !== "object" || json.error) return null;
  const total = json.safetensors?.total;
  return {
    paramsB: typeof total === "number" && total > 0 ? Math.round(total / 1e8) / 10 : null,
    downloads: typeof json.downloads === "number" ? json.downloads : null,
    pipelineTag: typeof json.pipeline_tag === "string" ? json.pipeline_tag : null,
  };
}

export async function fetchHfCards(hfIds) {
  const cards = await pool(hfIds, 5, (id) => (id ? fetchHf(id) : null));
  return new Map(hfIds.map((id, i) => [id, cards[i]]));
}

#!/usr/bin/env node
/**
 * Weekly release notes: what changed in the free-model landscape this week.
 *
 * Why releases: the daily table updates are commits, and GitHub does not
 * notify watchers about commits. It does notify them about releases. One a
 * week is enough to be useful and not noise.
 *
 * Compares today's snapshot (data/models.json) with the newest history
 * snapshot that is at least 7 days older, and writes:
 *   release-notes.md   the body
 *   release-tag.txt    e.g. "week-2026-09-28"
 *   release-title.txt  e.g. "Free AI models — week of 28 Sep 2026: 2 new, 1 gone"
 *
 * Usage: node scripts/weekly-release.js [--today YYYY-MM-DD]
 * Never fails the workflow on odd data: missing fields degrade the notes.
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const HIST = join(ROOT, "data", "history");

const argToday = process.argv.indexOf("--today");
const today = argToday > -1 ? process.argv[argToday + 1] : new Date().toISOString().slice(0, 10);

const read = (p) => JSON.parse(readFileSync(p, "utf8"));
// `kind` exists since 2026-09-20; older snapshots listed everything as one table.
const isChat = (m) => m.kind !== "other";
const ranked = (snap) =>
  (snap.models ?? [])
    .filter(isChat)
    .filter((m) => typeof m.zo_score === "number")
    .sort((a, b) => b.zo_score - a.zo_score);

function baseline() {
  const cutoff = new Date(Date.parse(today) - 7 * 86_400_000).toISOString().slice(0, 10);
  const files = existsSync(HIST) ? readdirSync(HIST).filter((f) => /^\d{4}-\d{2}-\d{2}\.json$/.test(f)).sort() : [];
  const older = files.filter((f) => f.slice(0, 10) <= cutoff);
  const pick = older.length ? older[older.length - 1] : files[0];
  return pick ? { date: pick.slice(0, 10), snap: read(join(HIST, pick)) } : null;
}

const now = read(join(ROOT, "data", "models.json"));
const before = baseline();

const chatNow = (now.models ?? []).filter(isChat);
const chatBefore = before ? (before.snap.models ?? []).filter(isChat) : [];

// Compare against EVERY model in the other snapshot, not just its chat ones:
// a model that moved to the "not a chat model" list (Lyria, 2026-09-20) is
// still free, so it is neither new nor gone.
const allIdsNow = new Set((now.models ?? []).map((m) => m.id));
const allIdsBefore = new Set(before ? (before.snap.models ?? []).map((m) => m.id) : []);
const added = before ? chatNow.filter((m) => !allIdsBefore.has(m.id)) : [];
const gone = before ? chatBefore.filter((m) => !allIdsNow.has(m.id)) : [];

const topNow = ranked(now)[0] ?? null;
const topBefore = before ? ranked(before.snap)[0] ?? null : null;
const topChanged = topNow && topBefore && topNow.id !== topBefore.id;

const fmtDate = (d) =>
  new Date(`${d}T00:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
const link = (m) => (m.source ? `[${m.name}](${m.source})` : m.name);
const ctx = (n) => (!n ? "" : n >= 1_000_000 ? ` · ${Math.round(n / 100_000) / 10}M context` : ` · ${Math.round(n / 1000)}K context`);

const lines = [];
lines.push(`**${chatNow.length} free chat models** tracked on ${fmtDate(today)}${before ? `, against ${chatBefore.length} on ${fmtDate(before.date)}` : ""}.`);
lines.push("");

if (topNow) {
  if (topChanged) {
    lines.push(`### New #1: ${topNow.name}`);
    lines.push(`Replaces ${topBefore.name} at the top of the ranking.`);
  } else {
    lines.push(`### #1 this week: ${topNow.name}`);
  }
  lines.push("");
  const top5 = ranked(now).slice(0, 5);
  lines.push("| # | Model | Score |");
  lines.push("|---|---|---|");
  top5.forEach((m, i) => lines.push(`| ${i + 1} | ${link(m)} | ${m.zo_score} |`));
  lines.push("");
}

lines.push(`### New this week (${added.length})`);
lines.push(added.length ? added.map((m) => `- ${link(m)} — ${m.provider}${ctx(m.context_window)}`).join("\n") : "- None.");
lines.push("");

if (before) {
  lines.push(`### No longer free, or withdrawn (${gone.length})`);
  lines.push(gone.length ? gone.map((m) => `- ${m.name} — ${m.provider}`).join("\n") : "- None.");
  lines.push("");
}

lines.push("---");
lines.push(`Full table, updated daily: [README](../../#free-models-auto-updated-daily) · raw data: [\`data/models.json\`](../../blob/main/data/models.json)`);
lines.push("");
lines.push(
  `Scores come from the open score in this repo ([\`scoring/score.js\`](../../blob/main/scoring/score.js), 0–100). ` +
    `Since 2026-10-10 it is computed here from public data, without production penalties, so numbers before that date are lower.`,
);

const tag = `week-${today}`;
const parts = [];
if (added.length) parts.push(`${added.length} new`);
if (gone.length) parts.push(`${gone.length} gone`);
if (topChanged) parts.push("new #1");
const title = `Free AI models — week of ${fmtDate(today)}${parts.length ? `: ${parts.join(", ")}` : ""}`;

writeFileSync(join(ROOT, "release-notes.md"), lines.join("\n") + "\n");
writeFileSync(join(ROOT, "release-tag.txt"), tag);
writeFileSync(join(ROOT, "release-title.txt"), title);
console.log(title);
console.log(`tag: ${tag} · baseline: ${before?.date ?? "none"}`);
